package ru.neverland.townymarket;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.locks.ReentrantLock;
import org.bukkit.configuration.file.YamlConfiguration;
import ru.neverland.core.*;
import ru.neverland.townymarket.personal.*;
import static ru.neverland.townymarket.personal.LimitBook.*;
public final class PersonalLimitPersistenceSmoke {
    static int checks;static void check(boolean good,String why){checks++;if(!good)throw new AssertionError(why);}static <T>T done(CompletionStage<T> f)throws Exception{return f.toCompletableFuture().get(5,TimeUnit.SECONDS);}interface Work{void run()throws Exception;}static void rejected(Work action,String why)throws Exception{try{action.run();}catch(Exception e){check(true,why);return;}throw new AssertionError(why);}
    static boolean ledgerResponsive(CompletionStage<?> blocked)throws InterruptedException{
        long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(1);
        while(System.nanoTime()<deadline&&!blocked.toCompletableFuture().isDone()){
            if(SuiteState.tryRun("storage delay",()->{}))return true;
            Thread.sleep(2); // A short publishing transition may legitimately own the ledger.
        }
        return false;
    }
    public static void main(String[] args)throws Exception{
        var dir=Files.createTempDirectory("personal-market-ack-");var file=dir.resolve("personal-orders.yml");var repo=new LimitRepository(file);repo.load();UUID buyer=UUID.randomUUID(),seller=UUID.randomUUID(),buy=UUID.randomUUID(),sell=UUID.randomUUID(),br=UUID.randomUUID(),sr=UUID.randomUUID();
        var before=repo.state();var pending=LimitBook.prepareOrder(before,buy,br,buyer,Side.BUY,"STONE",25,100,1000);var field=AtomicFiles.class.getDeclaredField("writers");field.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)field.get(null);var lock=locks.computeIfAbsent(file.toAbsolutePath().normalize(),p->new ReentrantLock());CompletionStage<State> receipt;lock.lock();try{receipt=repo.commit(before,pending);check(repo.busy()&&repo.state().orders().isEmpty()&&!receipt.toCompletableFuture().isDone(),"unconfirmed funding intent stays invisible while actual writer blocked");check(ledgerResponsive(receipt),"blocked writer never occupies suite ledger");rejected(()->done(repo.commit(before,pending)),"concurrent intent cannot overwrite accepted pending save");}finally{lock.unlock();}done(receipt);check(repo.state().receipts().get(br).status()==ReceiptStatus.PENDING,"durable pending exists before external money mutation");done(repo.prepareClose());
        var loaded=new LimitRepository(file);loaded.load();check(loaded.state().equals(pending)&&LimitBook.match(loaded.state(),1001,20).equals(pending),"restart neither repeats debit nor matches unconfirmed funds");var funded=LimitBook.resolve(loaded.state(),br,true,1002);funded=LimitBook.prepareOrder(funded,sell,sr,seller,Side.SELL,"STONE",10,80,1003);funded=LimitBook.resolve(funded,sr,true,1004);funded=LimitBook.match(funded,1005,20);done(loaded.commit(loaded.state(),funded));check(loaded.state().cash(seller)==1000&&loaded.state().item(buyer,"STONE")==10,"confirmed same-image fill keeps seller proceeds and buyer mailbox");
        String text=LimitRepository.encode(funded);var yaml=new YamlConfiguration();yaml.loadFromString(text);check(LimitRepository.decode(yaml).equals(funded),"exact schema roundtrip retains receipts filled orders and balances");UUID claim=UUID.randomUUID();var claiming=LimitBook.claimCash(funded,claim,seller,1000,1006);done(loaded.commit(funded,claiming));done(loaded.prepareClose());var reopened=new LimitRepository(file);reopened.load();check(reopened.state().cash(seller)==0&&reopened.state().receipts().get(claim).status()==ReceiptStatus.PENDING,"restart does not expose or replay uncertain payout");var repaired=LimitBook.resolve(reopened.state(),claim,false,1007);done(reopened.commit(reopened.state(),repaired));check(reopened.state().cash(seller)==1000,"verified unpaid payout restores only backed proceeds");
        var saved=reopened.state();Files.delete(file);Files.createDirectory(file);Files.writeString(file.resolve("keep"),"keep");rejected(()->done(reopened.commit(saved,LimitBook.cancel(saved,buyer,buy,1008))),"real file replacement failure rejects new cancellation");check(reopened.readable()&&!reopened.writable()&&reopened.state().equals(saved),"disk failure preserves last confirmed reservations and claims");done(reopened.prepareClose());
        var corrupted=new YamlConfiguration();corrupted.loadFromString(text);corrupted.set("wallets."+seller,1001);rejected(()->LimitRepository.decode(corrupted),"forged extra personal money fails conservation validation");corrupted.set("schema",3);rejected(()->LimitRepository.decode(corrupted),"unknown schema never resets journal");
        archive();
        System.out.println("PersonalLimitPersistenceSmoke PASS "+checks+" checks");
    }
    private record Seed(State state,UUID owner,UUID oldest,UUID funding){}
    private static Seed seed(){
        UUID owner=UUID.randomUUID(),order=UUID.randomUUID(),funding=UUID.randomUUID(),oldest=null;State state=LimitBook.prepareOrder(LimitBook.empty(),order,funding,owner,Side.BUY,"STONE",1,2000,1);state=LimitBook.resolve(state,funding,true,2);state=LimitBook.cancel(state,owner,order,3);
        for(int i=0;i<1025;i++){UUID id=UUID.randomUUID();if(oldest==null)oldest=id;state=LimitBook.claimCash(state,id,owner,1,10+i*2);state=LimitBook.resolve(state,id,true,11+i*2);}
        return new Seed(state,owner,oldest,funding);
    }
    private static String schemaOne(State state)throws Exception{var y=new YamlConfiguration();y.loadFromString(LimitRepository.encode(state));y.set("schema",1);y.set("claim-checkpoint",null);return y.saveToString();}
    private static Path firstArchive(Path dir)throws Exception{try(var files=Files.list(dir.resolve("personal-orders-claims"))){return files.filter(p->p.getFileName().toString().endsWith(".yml")).sorted().findFirst().orElseThrow();}}
    private static void archive()throws Exception{
        var seed=seed();check(seed.state().cash(seed.owner())==975,"fixture has 2000 funded cents minus 1025 confirmed one-cent payouts");var dir=Files.createTempDirectory("personal-market-archive-");var file=dir.resolve("personal-orders.yml");Files.writeString(file,schemaOne(seed.state()));var repo=new LimitRepository(file);repo.load();check(repo.state().equals(seed.state()),"schema one migrates losslessly with empty checkpoint");
        var field=AtomicFiles.class.getDeclaredField("writers");field.setAccessible(true);@SuppressWarnings("unchecked")var locks=(Map<Path,ReentrantLock>)field.get(null);var lock=locks.computeIfAbsent(file.toAbsolutePath().normalize(),p->new ReentrantLock());CompletionStage<State> compacting;
        lock.lock();try{
            compacting=repo.compactHistory();long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(!Files.isDirectory(dir.resolve("personal-orders-claims"))&&System.nanoTime()<end)Thread.sleep(5);
            Path archive=null;while(archive==null&&System.nanoTime()<end){try{archive=firstArchive(dir);}catch(NoSuchElementException error){Thread.sleep(5);}}
            check(archive!=null&&!compacting.toCompletableFuture().isDone()&&repo.state().equals(seed.state()),"archive reaches disk before main checkpoint ACK and no receipt disappears early");check(ledgerResponsive(compacting),"archive I/O does not occupy suite state");
        }finally{lock.unlock();}
        var compact=done(compacting);check(compact.claimCheckpoint().sequence()==1&&compact.claimCheckpoint().paidCash().get(seed.owner())==513&&compact.cash(seed.owner())==975,"checkpoint carries exact archived payout total and unchanged available cash");check(compact.receipts().size()==513&&compact.receipts().containsKey(seed.funding()),"only old terminal claims pruned; funding and recent 512 claims retained");check(done(repo.lookupReceipt(seed.oldest())).status()==ReceiptStatus.DONE,"archived completed operation remains inspectable");
        var replay=LimitBook.claimCash(compact,seed.oldest(),seed.owner(),1,3000);rejected(()->done(repo.commit(compact,replay)),"archived ID cannot reserve or pay a second time");check(repo.writable()&&repo.state().equals(compact),"rejected replay does not alter reserve or disable healthy repository");
        UUID pending=UUID.randomUUID();var next=LimitBook.claimCash(compact,pending,seed.owner(),50,4000);UUID failed=null;
        for(int i=0;i<1025;i++){UUID id=UUID.randomUUID();if(failed==null)failed=id;next=LimitBook.claimCash(next,id,seed.owner(),1,5000+i*2);next=LimitBook.resolve(next,id,false,5001+i*2);}
        var second=done(repo.commit(compact,next));check(second.claimCheckpoint().sequence()==2&&second.claimCheckpoint().paidCash().get(seed.owner())==1025&&second.cash(seed.owner())==925,"failed retries compact without changing paid amount or backed wallet");check(second.receipts().get(pending).status()==ReceiptStatus.PENDING&&second.receipts().get(seed.funding()).status()==ReceiptStatus.DONE,"every unresolved claim and funding receipt survives repeated compaction");UUID failedArchived=failed;check(done(repo.lookupReceipt(failedArchived)).status()==ReceiptStatus.FAILED,"archived refusal retains exact outcome");var retryOld=LimitBook.claimCash(second,failedArchived,seed.owner(),1,9000);rejected(()->done(repo.commit(second,retryOld)),"archived failed ID cannot be reused with a new result");done(repo.prepareClose());
        var loaded=new LimitRepository(file);loaded.load();check(loaded.state().equals(second)&&done(loaded.lookupReceipt(seed.oldest())).cents()==1,"restart verifies archive chain and restores exact checkpoint and receipt evidence");var restored=LimitBook.resolve(loaded.state(),pending,false,9001);done(loaded.commit(loaded.state(),restored));check(loaded.state().cash(seed.owner())==975,"pending reconciliation after archive restart restores only unpaid fifty cents");done(loaded.prepareClose());
        var async=new LimitRepository(file);CompletionStage<State> loading;try(var guard=SuiteState.guard()){loading=async.loadAsync();check(!async.readable()&&async.busy()&&!loading.toCompletableFuture().isDone(),"runtime load defers disk verification and publication outside the suite lock");}check(done(loading).cash(seed.owner())==975,"asynchronous archive verification publishes conserved balance");done(async.prepareClose());
        Path archived=firstArchive(dir);String intact=Files.readString(archived);Files.writeString(archived,intact+"# changed\n");var tampered=new LimitRepository(file);rejected(tampered::load,"archive hash mismatch cannot silently discard payout history");check(!tampered.readable(),"corrupt archive leaves market unreadable");done(tampered.prepareClose());Files.writeString(archived,intact);Files.delete(archived);var missing=new LimitRepository(file);rejected(missing::load,"missing referenced archive rejects journal instead of restoring already paid cash");done(missing.prepareClose());
        var crashDir=Files.createTempDirectory("personal-market-archive-tail-");var crashFile=crashDir.resolve("personal-orders.yml");String old=schemaOne(seed.state());Files.writeString(crashFile,old);var broken=new LimitRepository(crashFile);broken.load();Files.delete(crashFile);Files.createDirectory(crashFile);Files.writeString(crashFile.resolve("keep"),"keep");rejected(()->done(broken.compactHistory()),"main checkpoint write can fail after durable archive without losing active proofs");check(broken.state().equals(seed.state())&&Files.exists(firstArchive(crashDir)),"failed checkpoint leaves full acknowledged state and harmless orphan archive");done(broken.prepareClose());Files.delete(crashFile.resolve("keep"));Files.delete(crashFile);Files.writeString(crashFile,old);var recovered=new LimitRepository(crashFile);recovered.load();check(recovered.state().equals(seed.state()),"unreferenced archive tail is ignored on restart");var recoveredState=done(recovered.compactHistory());check(recoveredState.claimCheckpoint().sequence()==1&&recoveredState.cash(seed.owner())==975,"same immutable archive can be safely reused after checkpoint failure");done(recovered.prepareClose());
    }
}
